package com.rekluzlabs.makokolorize.data.modelimport android.content.Contextimport kotlinx.coroutines.Dispatchersimport kotlinx.coroutines.ensureActiveimport kotlinx.coroutines.withContextimport okhttp3.OkHttpClientimport okhttp3.Requestimport java.io.Fileimport java.io.FileOutputStreamimport java.util.concurrent.TimeUnitclass ModelRepository(private val context: Context) {    private val modelDir: File        get() = File(context.filesDir, "models")    private val modelFile: File        get() = File(modelDir, MODEL_FILENAME)    private val scunetModelFile: File        get() = File(modelDir, SCUNET_MODEL_FILENAME)    fun isModelDownloaded(): Boolean {        return modelFile.exists() &&               modelFile.length() >= (MODEL_SIZE_BYTES - 1_000_000L)    }    fun isScunetModelDownloaded(): Boolean {        return scunetModelFile.exists() &&               scunetModelFile.length() >= (SCUNET_MODEL_SIZE_BYTES - 1_000_000L)    }    fun deleteInvalidModel() {        if (modelFile.exists()) {            modelFile.delete()        }    }    fun deleteInvalidScunetModel() {        if (scunetModelFile.exists()) {            scunetModelFile.delete()        }    }    fun getModelPath(): String = modelFile.absolutePath    fun getScunetModelPath(): String = scunetModelFile.absolutePath    fun getFreeSpaceBytes(): Long = modelDir.parentFile?.freeSpace ?: 0L    suspend fun downloadModel(onProgress: (Float) -> Unit): Result<Unit> =        downloadFile(MODEL_URL, modelFile, onProgress)    suspend fun downloadScunetModel(onProgress: (Float) -> Unit): Result<Unit> =        downloadFile(SCUNET_MODEL_URL, scunetModelFile, onProgress)    private suspend fun downloadFile(        url: String,        file: File,        onProgress: (Float) -> Unit    ): Result<Unit> = withContext(Dispatchers.IO) {        try {            ensureActive()            modelDir.mkdirs()            val client = OkHttpClient.Builder()                .connectTimeout(30, TimeUnit.SECONDS)                .readTimeout(120, TimeUnit.SECONDS)                .build()            val request = Request.Builder().url(url).build()            val response = client.newCall(request).execute()            if (!response.isSuccessful) {                return@withContext Result.failure(Exception("Download failed (${response.code})"))            }            val body = response.body ?: return@withContext Result.failure(Exception("Empty response"))            val contentLength = body.contentLength()            body.byteStream().use { input ->                FileOutputStream(file).use { output ->                    val buffer = ByteArray(8192)                    var totalRead = 0L                    var read: Int                    while (input.read(buffer).also { read = it } != -1) {                        ensureActive()                        output.write(buffer, 0, read)                        totalRead += read                        if (contentLength > 0) {                            onProgress(totalRead.toFloat() / contentLength.toFloat())                        }                    }                }            }            if (!file.exists() || file.length() == 0L) {                return@withContext Result.failure(Exception("Download produced empty file"))            }            Result.success(Unit)        } catch (e: Exception) {            if (file.exists()) file.delete()            Result.failure(e)        }    }    companion object {        private const val MODEL_FILENAME = "ddcolor_paper_tiny.onnx"        private const val SCUNET_MODEL_FILENAME = "SCUNet-PSNR.onnx"        const val MODEL_URL = "https://github.com/rekluzlabs/Makokolor/releases/download/ddcolor-tiny/ddcolor_paper_tiny.onnx"        const val MODEL_SIZE_BYTES = 258_000_000L        const val SCUNET_MODEL_URL = "https://github.com/rekluzlabs/Makokolor/releases/download/scunet/SCUNet-PSNR.onnx"        const val SCUNET_MODEL_SIZE_BYTES = 87_000_000L        const val REQUIRED_FREE_SPACE = 400_000_000L    }}